  lazy var data: JSON = try! JSON.parse(Self.fixtures)

  func status(_ json: JSON?) -> BoxStatus? {
    guard let json, !json.isNull else { return nil }
    return BoxStatus(json: json)
  }

  func read(_ text: String) -> ComputerReadState { ComputerReadState(rawValue: text)! }

  func testPhases() {
    for item in data["phases"]!.array! {
      let s = status(item["status"])
      XCTAssertEqual(ComputerPhase.of(s, ensuring: item["ensuring"]!.bool!).rawValue, item["phase"]!.string!, "\(item)")
      XCTAssertEqual(s?.screenURL != nil, item["usable"]!.bool!, "\(item)")
    }
    XCTAssertEqual(data["phases"]!.array!.count, 16)
  }

  func testPlaceholders() {
    func check(_ got: ComputerPlaceholder?, _ want: JSON, _ label: String) {
      XCTAssertEqual(got?.message, want["message"]!.string!, label)
      XCTAssertEqual(got?.percent, want["progressPercent"]?.double, label)
      XCTAssertEqual(got?.isBusy, want["isBusy"]!.bool!, label)
      XCTAssertEqual(got?.hasRetry, want["hasRetry"]!.bool!, label)
    }
    for item in data["previews"]!.array! {
      let got = ComputerPlaceholder.preview(name: "Nora", read: read(item["read"]!.string!), phase: ComputerPhase(rawValue: item["phase"]!.string!)!, pullPercent: item["pull"]?.double)
      if item["shown"]!.bool! { check(got, item["copy"]!, "preview \(item)") } else { XCTAssertNil(got, "preview \(item)") }
    }
    for item in data["fulls"]!.array! {
      let got = ComputerPlaceholder.full(name: "Nora", read: read(item["read"]!.string!), phase: ComputerPhase(rawValue: item["phase"]!.string!)!, pullPercent: item["pull"]?.double, hasHelpers: item["helpers"]!.bool!)
      check(got, item["copy"]!, "full \(item)")
    }
    XCTAssertEqual(data["previews"]!.array!.count + data["fulls"]!.array!.count, 108)
  }

  func testHelpersAndStrip() {
    let helpers = ["a", "b", "c"].map { ComputerHelper(subagentId: $0, title: $0) }
    for item in data["focus"]!.array! {
      let list = Array(helpers.prefix(item["count"]!.int!))
      XCTAssertEqual(ComputerHelper.focused(list, asked: item["asked"]?.string), item["out"]?.string)
    }
    let rows: JSON = [["subagentId": "1", "subagentType": "computerUse", "status": "running", "title": " Browse "],
                      ["subagentId": "2", "subagentType": "computerUse", "status": "done", "title": "Old"],
                      ["subagentId": "3", "subagentType": "task", "status": "running", "title": "Think"],
                      ["subagentId": "4", "subagentType": "computerUse", "status": "running", "title": ""]]
    XCTAssertEqual(ComputerHelper.screens(rows.array!).map(\.title), ["Browse", "Subagent"])
    XCTAssertEqual(ComputerHelper.strip(4).shown, 4)
    XCTAssertNil(ComputerHelper.strip(4).more)
    XCTAssertEqual(ComputerHelper.strip(6).shown, 3)
    XCTAssertEqual(ComputerHelper.strip(6).more, 3)
    XCTAssertEqual(ComputerHelper.step(helpers, from: "c", by: 1), "a")
    XCTAssertEqual(ComputerHelper.step(helpers, from: "a", by: -1), "c")
    XCTAssertNil(ComputerHelper.step(Array(helpers.prefix(1)), from: "a", by: 1))
  }

  func testPointerCrashesAndClipboard() {
    XCTAssertEqual(AgentPointer.scale(frameWidth: 1280), 1.8)
    XCTAssertEqual(AgentPointer.scale(frameWidth: 100), 0.75)
    XCTAssertEqual(AgentPointer.scale(frameWidth: 400), 400 / 1280 * 2.85, accuracy: 1e-9)
    XCTAssertEqual(AgentPointer(x: 640, y: 400, type: "move").place(width: 320, height: 200).x, 160)
    XCTAssertEqual(AgentPointer.pressDelay(sinceMove: 0.2), 0.3, accuracy: 1e-9)

    var crashes = ScreenCrashes()
    let t0 = Date(timeIntervalSince1970: 0)
    XCTAssertTrue(crashes.crashed(at: t0))
    XCTAssertTrue(crashes.crashed(at: t0.addingTimeInterval(30)))
    XCTAssertTrue(crashes.crashed(at: t0.addingTimeInterval(60)))
    XCTAssertFalse(crashes.crashed(at: t0.addingTimeInterval(80)))
    XCTAssertTrue(crashes.gaveUp)
    crashes.reset()
    XCTAssertTrue(crashes.crashed(at: t0.addingTimeInterval(200)))
    var spaced = ScreenCrashes()
    for i in 0..<6 { XCTAssertTrue(spaced.crashed(at: t0.addingTimeInterval(Double(i) * 61))) }

    var clip = ClipboardBridge()
    XCTAssertNil(clip.fromBox(""))
    XCTAssertEqual(clip.fromBox("hello"), "hello")
    XCTAssertNil(clip.fromBox("hello"))
    clip.sent("mine")
    XCTAssertNil(clip.fromBox("mine"))
    XCTAssertTrue(clip.mayRead(at: t0))
    XCTAssertFalse(clip.mayRead(at: t0.addingTimeInterval(0.1)))
    XCTAssertTrue(clip.mayRead(at: t0.addingTimeInterval(0.35)))
  }

  func testStreamReasons() {
    typealias C = ComputerStreamReason.Change
    let cases: [(String, C)] = [
      ("[SimeonScreen] state=connected status=\"\" dialog=none", .clear),
      ("local docker: gateway ready", .keep),
      ("box reachability outcome=timeout method=listAgents cause=deadline baseUrl=x", .set("The computer's gateway did not answer \"listAgents\" within the deadline.")),
      ("box reachability outcome=network method=health cause=ECONNRESET baseUrl=x", .set("The computer's gateway could not be reached for \"health\" (ECONNRESET).")),
      ("box reachability outcome=box_blocked method=a cause=b", .set("The computer is blocked or paused.")),
      ("box reachability outcome=http_500 method=a cause=b", .set("The computer's gateway failed \"a\": http_500 (b).")),
      ("guest load FAILED code=-105 (ERR_NAME_NOT_RESOLVED) url=x mainFrame=true", .set("The screen page did not load (ERR_NAME_NOT_RESOLVED, -105).")),
      ("guest renderer gone reason=crashed", .set("The screen page crashed.")),
      ("[SimeonScreen] state=disconnected status=\"Failed to connect to server\" dialog=none", .set("noVNC cannot reach the desktop's socket.")),
      ("[SimeonScreen] page error: boom at x.js:1", .set("Error inside the screen page: boom at x.js:1")),
      ("guest console[error] Uncaught TypeError", .set("Error inside the screen page: Uncaught TypeError")),
      ("guest loaded url=x", .keep),
    ]
    for (line, want) in cases { XCTAssertEqual(ComputerStreamReason.change(for: line), want, line) }
    XCTAssertEqual(ComputerStreamReason.notice(lead: ComputerStreamReason.notConnecting, reason: nil, filePath: "/tmp/l.log"),
                   "The computer's screen isn't connecting. No reason was reported yet. Details: /tmp/l.log")
  }
}
